  h+=`<div class="mkcard">${mkSec('포지션별 전력 현황','1군 기준')}<table class="mkt"><thead><tr><th class="tn">포지션</th><th>보유(명)</th><th>권장(명)</th><th>전력 평가</th><th>현황</th></tr></thead><tbody>${['sp','rp','c','inf','of'].map(k=>{const [n,txt]=stat(k);return `<tr><td class="tn">${K[k]} (${{sp:'SP',rp:'RP',c:'C',inf:'INF',of:'OF'}[k]})</td><td class="tc">${cnt[k]}</td><td class="tc">${rec[k]}</td><td class="tc">${mkBlocks(n,5)}</td><td class="tc st ${txt}">${txt}</td></tr>`;}).join('')}</tbody></table></div>`;
