    const advice=dg.weak?[`${SL.ATTR_KO[dg.best]||dg.bestTxt}은 안정적`,`${SL.ATTR_KO[dg.weak]} 보완 필요 — 훈련 방향 「${SL.ATTR_KO[dg.weak]}」 권장`,res.has(sel.id)?'당분간 2군에서 실전 경험 누적 권장':'1군 출장 시간 유지']:[`${dg.bestTxt} 안정적`,'뚜렷한 약점 없음',res.has(sel.id)?'콜업 검토 가능':'주전 유지'];
