  if(p.awards&&p.awards.length){const A=p.awards.slice().reverse();const cnt=k=>A.filter(a=>a.k===k).length;h+=`<div class="mkcard" style="padding:0">${mkSec('수상 기록',`총 ${A.length}회`)}<div style="padding:8px 12px"><div class="row wrap" style="gap:6px;margin-bottom:6px">${[['mvp','MVP'],['roy','신인왕'],['gg','골든글러브'],['title','타이틀']].filter(x=>cnt(x[0])).map(x=>`<span class="chip y">${x[1]} ${cnt(x[0])}회</span>`).join('')}</div>${A.map(a=>`<div class="small" style="padding:5px 0;border-bottom:1px dashed var(--line)">🏆 <b>${mkYear(a.s)}시즌</b> ${esc(a.lab)}${a.tn?` <span class="muted">· ${esc(a.tn)}</span>`:''}</div>`).join('')}</div></div>`;}
  {const rr=(p.rhist||[]).map(x=>({s:x.s,tn:x.tn,st:x.st})).concat(hasSt(p.res)?[{s:S.season,tn:t?t.name:'-',st:p.res}]:[]).reverse();if(rr.length)h+=`<div class="mkcard" style="padding:0">${mkSec('2군 기록')}<table class="mkt mini"><thead><tr><th>시즌</th><th class="tn">소속</th>${H}</tr></thead><tbody>${rr.slice(0,6).map(r=>`<tr><td class="tc">${mkYear(r.s)}</td><td class="tn"><span class="tcl" style="max-width:80px">${esc(r.tn)}</span></td>${statRow(p,r.st).map(x=>`<td class="tc">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
