  h+=`<div class="mkcard" style="padding:0">${mkSec('계약 상태')}<table class="kvt2 two"><tr><td>역할</td><td>${esc(mine?role(p):roleCmp(p).split(' (')[0])}</td><td>만족도</td><td class="${sat[1]}"><b>${sat[0]}</b></td></tr></table>${mine?`<div class="small muted" style="padding:6px 12px">${esc(SL.contractText(p))}${p.renewed===S.season?' · 올해 재계약함':''}</div>`:''}</div>`;
