function go(view){const y=window.scrollY||0;if(ui.view){ui.view._y=y;ui.stack.push(ui.view);}else ui.listY={tab:ui.tab,sub:ui.sub[ui.tab],y};if(ui.stack.length>8)ui.stack.shift();ui.view=view;closeModal();render();if(isWide()){const r=$('#rpane');if(r)r.scrollTop=0;}else scrollTop();}
Object.assign(A,{back(){const v=ui.stack.pop()||null;ui.view=v;closeModal();render();const y=v?v._y:(ui.listY&&ui.listY.tab===ui.tab&&ui.listY.sub===ui.sub[ui.tab]?ui.listY.y:0);try{window.scrollTo(0,y||0);}catch(e){}}});

