function once(k,ms){const n=Date.now();ui._once=ui._once||{};if(ui._once[k]&&n-ui._once[k]<(ms||350))return false;ui._once[k]=n;return true;}
// 비용 네 칸: 바로 지출 · 해마다 연봉 · 첫해(올해) 지급 · 총보장액
function costBox(pid,f){const c=SL.negCost(pid,{salary:f.salary,years:f.years,bonus:f.bonus});if(!c)return '';const parts=[];if(c.bonus)parts.push(`계약금 ${Ms(c.bonus)}`);if(c.fee)parts.push(`이적료 ${Ms(c.fee)}`);if(c.signFee)parts.push(`FA 영입 비용 ${Ms(c.signFee)} (선수 가치의 10%, 자동)`);
  return `<div class="cost2"><div><span>계약 때 바로 지출</span><b>${Ms(c.now)}</b><small>${parts.join(' + ')||'없음'}${c.now?' · 이적 예산':''}</small></div><div><span>해마다 연봉</span><b>${Ms(c.salary)}</b><small>× ${c.years}년 · 연봉 예산</small></div><div><span>${c.off?`${mkYear(c.season)}시즌 지급`:'올해 지급'}</span><b class="o">${Ms(c.year1)}</b><small>${c.off?'첫해 연봉 + 바로 지출':`남은 시즌 연봉 ${Ms(c.thisYr)} + 바로 지출`}</small></div><div><span>총보장액</span><b>${Ms(c.total)}</b><small>${c.years}년 연봉${c.bonus?' + 계약금':''}${c.signFee?' + 영입 비용':''}${c.fee?' · 이적료 별도':''}</small></div></div>`;}
// 지금 조건이면 어떻게 되나 + 협상 규칙 (엔진 판정과 같은 계산)
function ruleBox(pid,f){const r=SL.negPreview(pid,{salary:f.salary,years:f.years,bonus:f.bonus,promise:f.promise});if(!r)return '';
  const Z={sure:['ok','✅ 이 조건이면 수락','선수가 바로 사인합니다'],wait:['due','⏳ 결정 대기',`${r.dec}주차 끝에 다른 구단 조건과 비교해 고릅니다 (그 전에 올려 다시 제시 가능)`],close:['due',r.comp?'↘ 거절 — 경쟁 구단에 밀림':'↘ 거절 — 요구에 근접',r.comp?'개인 요구는 채웠지만 선수 평가가 경쟁 구단보다 낮음':'요구액을 다시 알려 줌'],low:['bad','✖ 거절 — 차이 큼','요구와 차이가 큼']}[r.zone];
  let after='';if(r.dMood){after=`분위기 ${r.mood}% → ${r.mood1}% (${r.dMood})`;if(r.walk)after+=' — 20% 밑이라 선수가 떠나 이번 시즌 다시 앉지 않음';else if(r.leave)after+=' — 20% 밑이라 이번 테이블 종료';else if(r.left<=1)after+=' — 마지막 제시라 테이블 종료';if(r.up8)after+=' · 35% 밑부터 요구액 +8%';}
  return `<div class="rule2 ${Z[0]}"><div class="row sb" style="gap:6px;flex-wrap:wrap"><b>${Z[1]}</b><span class="small">제안 ${r.left}회 남음 · 다시 열기 ${r.tables}번</span></div><div class="small">${esc(Z[2])}${after?' · '+esc(after):''}</div><details class="small"><summary>협상 규칙</summary>거절될 때마다 분위기가 내려갑니다 (요구에 가까우면 ${r.major?'−5':'−4'}, 차이가 크면 ${r.major?'−15':'−18'}). 분위기 20% 밑이면 ${r.major?'테이블이 닫히고':'선수가 떠나 이번 시즌 다시 앉지 않고'}, 제시 횟수를 다 쓰면 테이블이 닫힙니다 (다시 열 기회가 남아 있으면 다시 협상). ${r.major?'주요 FA는 요구를 채우고 경쟁 구단보다 확실히(8%) 앞서면 바로 사인, 비슷하면 결정 주까지 기다립니다. 분위기가 35% 밑이면 요구 총액 +6%, 75% 이상이면 −3%.':'분위기 35% 밑이면 요구액 +8%, 75% 이상이면 −4%. 3년 이상 계약은 요구 −5%, 1년 계약은 +8%. 출장을 원하는 선수는 주전 약속 때 −8%. 계약금은 해마다 나눠 80%만 연봉처럼 칩니다.'}</details></div>`;}
