function renewWhyTxt(p){const w=SL.renewWhy(p);const a=[];if(w.d!=null)a.push(`올해 능력 ${w.ovr0} → ${w.ovr1} (${w.d>0?'+':w.d<0?'':'±'}${w.d})`);a.push(w.base==='mk'?`능력 시세 ${Ms(w.mk)} (지금 연봉 +5%보다 높음)`:`지금 연봉 ${Ms(w.cur)} +5% (연봉은 깎지 않음 · 능력 시세 ${Ms(w.mk)})`);a.push(...w.mods);return a.join(' · ');}
function renewWhyShort(p){const w=SL.renewWhy(p);const a=[];if(w.d!=null)a.push(`능력 ${w.d>0?'+':w.d<0?'':'±'}${w.d}`);a.push(w.base==='mk'?'시세':'현 연봉+5%');if(w.mods.length)a.push(w.mods.map(x=>x.replace(/^(\S+).*?([+−]\d+%)$/,'$1 $2')).join(' · '));return a.join(' · ');}
