  const ti=teams.findIndex(x=>x.id===t.id);const prev=teams[(ti-1+teams.length)%teams.length],next=teams[(ti+1)%teams.length];
  const list=(team,sd)=>team.roster.map(id=>S.players[id]).filter(p=>p&&!p.loan&&(side==='P'?SL.isPitcher(p):!SL.isPitcher(p))).sort((a,b)=>SL.calcOvr(b)-SL.calcOvr(a));
  const core=SL.tradeCore(t);const W=SL.tradeWants(t);
