// v80 (R064): 선수 상세 능력·기록 탭 — 아래 칸(하위 탭)으로 나눠 한 화면에. 능력: 능력치 · 그래프 · 훈련 · 진단 · 성장 기록 / 기록: 시즌 · 리그 비교 · 세부 지표
const PV_SUB={ability:[['stat','능력치'],['graph','그래프'],['train','훈련'],['diag','진단'],['grow','성장 기록']],record:[['season','기본 기록'],['cmp','리그 비교'],['adv','세부 지표']],growth:[['trend','능력 변화'],['train','훈련 기록']]};
