  if(tab==='growth')box.querySelectorAll(':scope>.sg2').forEach(d=>{while(d.firstChild)d.before(d.firstChild);d.remove();});pv.querySelectorAll('.actbar').forEach(e=>e.remove());box.querySelectorAll(':scope>.card.sj').forEach(e=>e.remove());
