  const al=box.querySelector('.ablink');if(al){const c=document.createElement('div');c.className='card ablinkc';c.innerHTML='<div class="hd"><h3>능력치 → 기록</h3></div>';c.appendChild(al);const cmp=[...box.children].find(e=>/주요 기록 비교/.test(pvTitle(e)));(cmp||box.lastElementChild).after(c);}
  const kids=[...box.children].slice([...box.children].indexOf(tabs)+1).filter(e=>e.nodeType===1&&!e.matches('.mkbtn2'));const G={};for(const e of kids){const g=pvGroup(tab,e);e.dataset.pg=g;(G[g]=G[g]||[]).push(e);}
  const L=PV_SUB[tab].filter(x=>G[x[0]]);if(L.length<2)return;if(ui.pvSubPid!==v.id){ui.pvSub={};ui.pvSubPid=v.id;}ui.pvSub=ui.pvSub||{};let cur=ui.pvSub[tab];if(!G[cur])cur=L[0][0];
