  const pidOf=el=>{const r=el.closest('tr.lurow');if(r)return {pid:+r.dataset.pid,i:+r.dataset.i,kind:'row'};const d=el.closest('.dia .dslot');if(d){const ps=(d.getAttribute('onclick')||'').match(/diaPick\('(\w+)'\)/);const ut=SL.userTeam();const pid=ps?ut.lineup.find(id=>ut.pos[id]===ps[1]):null;return {pid:pid==null?null:pid,ps:ps?ps[1]:null,kind:'slot'};}return null;};
