  const move=(x,y)=>{if(!ghost)return;ghost.style.left=x+'px';ghost.style.top=y+'px';document.querySelectorAll('.ludrop').forEach(e=>e.classList.remove('ludrop'));ghost.style.display='none';const el=document.elementFromPoint(x,y);ghost.style.display='';const t=el&&(el.closest('tr.lurow')||el.closest('.dia .dslot'));if(t)t.classList.add('ludrop');};
