const EMO={'🏆':'trophy','✅':'ok','❌':'no','⚠':'warn','🔭':'scope','✍':'pen','📝':'pen','🤝':'deal','📋':'board','🗂':'board','💼':'case','👔':'case','⏳':'wait','⌛':'wait','🔍':'find','⚲':'find','👀':'eye','✉':'mail','👥':'users','👤':'user','🧢':'user','💰':'coin','💵':'coin','💱':'coin','🎟':'coin','✈':'globe','🌏':'globe','⚖':'scale','⚾':'ball','🥎':'ball','🏏':'ball','🎯':'target','☰':'menu','📅':'cal','🗓':'cal','🏷':'tag','🪧':'tag','🏋':'gym','💪':'gym','📊':'chart','📈':'chart','🔒':'lock','🔓':'unlock','🎙':'mic','📣':'mic','🏟':'park','🏢':'bldg','🏥':'bldg','🧤':'glove','👟':'run','🎽':'run','🧭':'compass','📖':'book','📰':'doc','📄':'doc','🌱':'sprout','⭐':'star','🎉':'flag','🩹':'med','⛑':'med','💾':'save','🎓':'grad','🛏':'bed','📺':'tv','💬':'talk','⚙':'gear','☑':'chk','☐':'box'};
const EMO_TXT={'✔':'✓','✖':'✕','⬆':'↑','⬇':'↓','➖':'−'};
const EMO_KEEP=new Set(['★','☆','✓','✕','✗','↔','↕']);
const EMO_RE=/[\u{1F1E6}-\u{1F1FF}]{2}|[\u{1F300}-\u{1FAFF}☀-➿⬆⬇⭐⏳⌛☰⚲]️?/gu;
const liSvg=k=>`<svg class="li" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${LI[k]}</svg>`;
function emoSwap(s,html){let hit=false;const r=s.replace(EMO_RE,m=>{const c=m.replace('️','');if(EMO_KEEP.has(c))return m;hit=true;
    if(/^[\u{1F1E6}-\u{1F1FF}]{2}$/u.test(c)){const cc=[...c].map(x=>String.fromCharCode(x.codePointAt(0)-0x1F1E6+65)).join('');return html?`\u0000cc${cc}\u0000`:cc;}
    if(EMO_TXT[c])return EMO_TXT[c];if(html&&EMO[c])return `\u0000i${EMO[c]}\u0000`;return '';});
  if(!hit)return null;let out=html?esc(r):r;if(html)out=out.replace(/\u0000cc([A-Z]{2})\u0000/g,'<span class="cc">$1</span>').replace(/\u0000i(\w+)\u0000/g,(m,k)=>liSvg(k));return out.replace(/^\s+(?=<svg)/,'');}
function unslopIcons(root){if(!root||typeof document==='undefined'||document.body.classList.contains('ingame'))return;
  if(root.nodeType===3)root=root.parentNode;if(!root||!root.querySelectorAll||root.closest&&root.closest('.gamev'))return;
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentNode;if(!p||/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.nodeName)||p.closest('svg,.gamev'))return NodeFilter.FILTER_REJECT;EMO_RE.lastIndex=0;return EMO_RE.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_SKIP;}});
  const list=[];while(w.nextNode())list.push(w.currentNode);
  for(const n of list){const p=n.parentNode;if(!p)continue;if(/^(OPTION|TITLE)$/.test(p.nodeName)){const t=emoSwap(n.nodeValue,false);if(t!=null)n.nodeValue=t.replace(/^\s+/,'');continue;}
    const h=emoSwap(n.nodeValue,true);if(h==null)continue;const t=document.createElement('template');t.innerHTML=h;p.replaceChild(t.content,n);}
  root.querySelectorAll('[placeholder],[title]').forEach(e=>{for(const a of ['placeholder','title']){const v=e.getAttribute(a);if(v){const t=emoSwap(v,false);if(t!=null)e.setAttribute(a,t.trim());}}});}
try{if(typeof MutationObserver!=='undefined'&&typeof document!=='undefined'&&document.body)new MutationObserver(ms=>{if(document.body.classList.contains('ingame'))return;for(const m of ms){if(m.type==='characterData'){unslopIcons(m.target);continue;}for(const n of m.addedNodes){if(n.nodeType===1&&n.classList&&n.classList.contains('li'))continue;unslopIcons(n);}}}).observe(document.body,{childList:true,subtree:true,characterData:true});}catch(e){}
