  h+=`<div class="card">${hd('트레이드 매물',`리빌딩·재정 회복 구단 · ${M.sell.length}명`)}${M.sell.map(x=>{const p=S.players[x.pid];return `<div class="prow" onclick="UI.openPlayer(${p.id})">${face(p,36)}<div class="grow" style="min-width:0"><div class="nm">${esc(p.name)} <span class="muted small" style="font-weight:400">${pos(p.pos)} · ${p.age}세 · ${nm(x.tid)}</span></div><div class="sub">종합 ${Math.round(SL.calcOvr(p))} · 연봉 ${Ms(p.contract?p.contract.salary:0)} · ${esc(x.why)}</div></div><button class="sm primary" onclick="event.stopPropagation();UI.thubGo(${x.tid},${p.id})">교환 후보 추가</button></div>`;}).join('')||'<div class="muted small">지금은 선수를 내놓는 구단이 없습니다 (리빌딩·재정 회복 구단이 생기면 나옵니다).</div>'}</div>`;
  h+=`<div class="card">${hd('우리 매물')}${M.ours.map(x=>{const p=S.players[x.pid];return `<div class="prow" onclick="UI.openPlayer(${p.id})">${face(p,36)}<div class="grow" style="min-width:0"><div class="nm">${esc(p.name)} <span class="muted small" style="font-weight:400">${pos(p.pos)} · ${p.age}세</span></div><div class="sub">${x.fits.length?`이 자리를 원하는 구단: ${x.fits.map(nm).join(', ')}`:'지금 이 자리를 원하는 구단은 없음'}</div></div>${x.fits.length?`<button class="sm ghost" onclick="event.stopPropagation();UI.thubGo(${x.fits[0]},null,${p.id})">교환</button>`:''}</div>`;}).join('')||`<div class="row sb small"><span class="muted">등록 매물 없음</span><button class="sm ghost" onclick="UI.go('market','list')">매물 등록</button></div>`}</div>`;
