// 「구해요」 영입 공고
const WANT_POS=[['ANY','아무 자리'],['P','투수'],['SP','선발'],['RP','불펜'],['B','야수'],['C','포수'],['1B','1루수'],['2B','2루수'],['3B','3루수'],['SS','유격수'],['LF','좌익수'],['CF','중견수'],['RF','우익수']];
