const WANT_AGE=[[40,'나이 무관'],[34,'34세 이하'],[30,'30세 이하'],[26,'26세 이하'],[23,'23세 이하']];
function wantHtml(){const W=SL.wantInfo();const f=ui.wantF=ui.wantF||{pos:'ANY',sal:0,age:40};if(W&&!W.waiting)W.seen=S.want.seen=true;const SRC={agent:'FA',club:'국내 구단',os:'해외'};
  const sel=(k,L)=>`<select class="sm on" onchange="UI.wantF('${k}',this.value)">${L.map(x=>`<option value="${x[0]}" ${String(f[k])===String(x[0])?'selected':''}>${x[1]}</option>`).join('')}</select>`;
  let h=`<div class="stv">${stvHead('영입 공고','')}<div class="small muted" style="margin:0 0 8px">찾는 자리·연봉·나이를 올리면 ${S.phase==='season'?'2일':'1주'} 뒤 FA 에이전트 · 국내 구단 · 해외 에이전트가 후보를 보내옵니다 (최대 5명). 후보를 눌러 바로 협상합니다.</div>
    <div class="mkfilt"><span class="lb">⚲</span>${sel('pos',WANT_POS)}${sel('sal',WANT_SAL)}${sel('age',WANT_AGE)}</div><div class="row" style="gap:6px;margin:8px 0"><button class="primary grow" onclick="UI.wantPost()">${W?'새 공고로 바꾸기':'공고 내기'}</button>${W?'<button class="ghost" onclick="UI.wantClear()">공고 내리기</button>':''}</div>`;
  if(W){const pk=(WANT_POS.find(x=>x[0]===W.pos)||[0,W.pos])[1];h+=`<div class="card">${hd('지금 공고',`${pk} · ${W.sal?Ms(W.sal)+' 이하':'연봉 제한 없음'} · ${W.age>=40?'나이 무관':W.age+'세 이하'}`)}`;
    if(W.waiting){const n=Math.max(0,W.ready-S.clock);h+=`<div class="muted small">답장을 기다리는 중 — ${n?`${n}${S.phase==='season'?'일':'주'} 뒤`:'곧'} 도착</div>`;}
    else if(!W.list.length)h+=`<div class="muted small">조건에 맞는 선수가 없다는 답이 왔습니다. 연봉·나이 조건을 넓혀 다시 내 보세요.</div>`;
    else h+=W.list.map(x=>{const p=x.p;if(!p)return '';const t=p.teamId!=null?S.teams[p.teamId]:null;return `<div class="prow" onclick="UI.openPlayer(${p.id})">${face(p,36)}<div class="grow" style="min-width:0"><div class="nm">${esc(p.name)} <span class="muted small" style="font-weight:400">${SL.POS_KO[p.pos]||p.pos} · ${p.age}세 · ${SRC[x.src]}</span></div><div class="sub">종합 ${Math.round(SL.calcOvr(p))} · 예상 연봉 ${Ms(x.ask)} · ${esc(x.from)}${t&&t.league!=='KR'?' · '+esc(t.name):''}</div></div>${x.gone?'<span class="small muted">영입함</span>':p.teamId!=null&&p.teamId===SL.userTeam().id?'':`<button class="sm primary" onclick="event.stopPropagation();UI.openTable(${p.id})">협상</button>`}</div>`;}).join('');
    h+=`</div>`;}
  return h+`</div>`;}
// 감독 → 내 실적: 도전 시나리오 · 구단주 요청 · 감독 칭호
function scenCardHtml(){const X=SL.scenInfo();if(!X)return '';const r=X.res;
  return `<div class="card scenc">${hd('도전 시나리오 · '+esc(X.name),r?(r.ok?'<b class="ok">성공</b>':'<b class="bad">실패</b>'):'진행 중')}<div class="small">${esc(X.pitch)}</div><div class="row sb small" style="margin-top:6px"><span>목표 <b>${esc(X.goal)}</b></span><span>${r?esc(r.why):`지금 ${X.rank}위`}</span></div>${X.from?`<div class="small muted">부임할 때 ${X.from.w}승 ${X.from.l}패 최하위 · 5위와 ${(+X.gap||0).toFixed(1)}경기 차</div>`:''}${X.who.length?`<div class="small muted">다친 주전: ${X.who.map(w=>`${esc(w.name)} ${w.inj?w.inj+'일 남음':'<span class="ok">복귀</span>'}`).join(' · ')}</div>`:''}<div class="small muted">성공하면 감독 칭호 「${esc((SL.TITLES.find(t=>t[0]===SL.SCEN[X.k].title)||[])[1]||'')}」</div></div>`;}
