/* v112 (R094): 시즌 결산 표 — 올해 | 내년 네 줄 (긴 문장 없이) */
function recapTable(){const R=SL.seasonRecap();if(!R)return '';const ut=SL.userTeam();const nx=p=>SL.inEntry(ut,p.id)?'1군 자리 지키기':'1군 경쟁 준비';const pl=x=>`<a class="pname" onclick="UI.closeModal();UI.openPlayer(${x.p.id})">${esc(x.p.name)}</a> <b class="${x.d>0?'up':x.d<0?'dn':''}">${x.d>0?'+':x.d===0?'±':''}${x.d}</b>`;
  const rows=[[`<span class="muted">순위</span> ${R.rank}위 · ${R.w}승 ${R.l}패`,!R.ps?'가을야구 재도전':R.ps==='champ'?'2연패 도전':R.ps==='ks'?'우승 재도전':'상위권 도전']];
  if(R.sign)rows.push([`<span class="muted">영입 성과</span> ${pl(R.sign)}`,nx(R.sign.p)]);if(R.grow)rows.push([`<span class="muted">최대 성장</span> ${pl(R.grow)}`,nx(R.grow.p)]);
  if(R.need.length)rows.push([`<span class="muted">보강 필요</span> ${R.need.map(x=>esc(x.ko)).join('·')}`,`<button class="sm ghost" onclick="UI.closeModal();UI.go('market','fa')">후보 찾기</button>`]);
  return `<table class="kvt recapt" style="text-align:left"><tr><td class="small">올해</td><td class="small muted">내년</td></tr>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</table>`;}
/* v115 (R097): 휴대폰에서 긴 선수 목록은 목록만 스크롤 — 위(구단 줄·탭·필터)와 아래(단추·메뉴)는 그대로 */
function fitLists(){const L=[...document.querySelectorAll('.content .fitl')];for(const el of L){el.style.maxHeight='';el.classList.remove('fitx');}if(isWide()||!L.length||document.querySelector('#modal'))return;
  const fixedTop=Math.min(innerHeight,...[...document.querySelectorAll('body *')].filter(e=>{const cs=getComputedStyle(e);if(cs.position!=='fixed')return false;const r=e.getBoundingClientRect();return r.height>0&&r.bottom>=innerHeight-2&&r.top>innerHeight/2;}).map(e=>e.getBoundingClientRect().top));
  for(const el of L){const r=el.getBoundingClientRect();let after=0;let n=el.nextElementSibling;while(n){if(n.offsetHeight)after+=n.getBoundingClientRect().height+8;n=n.nextElementSibling;}
    const avail=Math.floor(fixedTop-r.top-after-8+(document.scrollingElement.scrollTop||0)*0);if(avail>=220&&el.scrollHeight>avail){el.style.maxHeight=avail+'px';el.classList.add('fitx');}}}
window.addEventListener('resize',()=>{try{fitLists();}catch(e){}});
/* v115 (R098 QA): 겨울 선수 목록의 「지난 시즌」 칸 — 짧게 (긴 문장이 화면 밖으로 밀리던 것) */
// v116 (R098): 겨울 선수 목록 「지난 시즌」 칸 — 한 덩이로 짧게. 1군 기록이 거의 없으면 2군 기록(「2군 .300」)
function statMini(p){const l=lastSt(p);const thin=!l||(!(l.st.pa>=10)&&!(l.st.pOuts>=9));const rh=(p.rhist||[]).slice(-1)[0];const h1=l&&/^\d+시즌$/.test(l.label)?+l.label.replace('시즌',''):0;
  if(rh&&hasSt(rh.st)&&(rh.s>h1||(rh.s===h1&&thin))){const s=SL.statLine(p,rh.st);return `<span title="${rh.s}시즌 2군">2군 ${SL.isPitcher(p)?s.era:s.avg}</span>`;}
  if(!l||!hasSt(l.st))return '<span class="muted">-</span>';const s=SL.statLine(p,l.st);return SL.isPitcher(p)?`${s.era} · ${s.w}승`:`${s.avg} · ${s.hr}홈런`;}

